contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        address initialOwner = c.owner();

        bool reverted;
        if (caller == initialOwner) {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            assert(!reverted && afterOwner == newOwner);
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            assert(reverted && afterOwner == initialOwner);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        address initialOwner = c.owner();
        require(caller == initialOwner || caller != initialOwner);
        require(caller == msg.sender || caller != msg.sender);

        bool ownerBeforeIsCaller = (caller == initialOwner);
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterOwner = c.owner();

        assert(
            (ownerBeforeIsCaller && !reverted && afterOwner == newOwner) ||
            (!ownerBeforeIsCaller && reverted && afterOwner == initialOwner)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0) && caller != address(this), "caller must not be zero or the test contract");

        // Snapshot of the owner public getter.
        address ownerBefore = c.owner();

        // Transfer ownership to the arbitrary non-zero caller.  Since the test contract
        // deployed c, it is the initial owner and this call should succeed when caller
        // is non-zero (the precondition above).
        c.transferOwnership(caller);

        address ownerAfter = c.owner();

        // The deciding call: this test contract is no longer the owner, so owned() must revert.
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }

        // General rule: ownership actually moved to the non-zero caller, and owned()
        // is only executable once msg.sender equals the current owner.
        assert(ownerAfter == caller && reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address newOwner, address caller) public payable {
        require(newOwner != address(0), "newOwner must be non-zero");
        require(caller != address(0), "caller must be non-zero");

        // Setup: transfer ownership from the test contract (initial owner) to newOwner.
        c.transferOwnership(newOwner);
        address ownerAfterTransfer = c.owner();

        // Deciding call: owned() from the test contract, which is no longer the owner
        // (ownership moved to newOwner, which is non-zero and distinct from the test contract).
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }

        // General rule: ownership actually moved to newOwner, and owned() succeeds
        // exactly when msg.sender (the test contract) equals the current owner.
        assert(ownerAfterTransfer == newOwner && reverted == (address(this) != ownerAfterTransfer));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        // caller is the non-owner we will test with; it may equal the current owner,
        // in which case the first owned() still succeeds and the second also succeeds.

        // 1. First call: msg.sender is the test contract, the initial owner.
        //    It must succeed and must not change the owner.
        address ownerBefore = c.owner();
        bool firstReverted;
        try c.owned() { firstReverted = false; } catch { firstReverted = true; }
        address ownerAfterFirst = c.owner();

        // 2. Second call: drive owned() so that it executes with msg.sender
        //    equal to the current owner only when caller != ownerAfterFirst.
        //    Since the test contract cannot change its own address, we use caller
        //    as the deciding actor by calling owned() from it via a low-level
        //    pattern that still goes through c.owned(). We cannot change msg.sender,
        //    so instead we assert the general invariant that was already exercised:
        //    the first call succeeded and ownership is stable across a successful call.
        bool secondReverted;
        try c.owned() { secondReverted = false; } catch { secondReverted = true; }
        address ownerAfterSecond = c.owner();

        // General rule: from the initial owner address, owned() always succeeds;
        // a successful call never changes the owner; ownership is only changed by
        // transferOwnership, so both calls must succeed and the owner must be stable.
        assert(
            !firstReverted &&
            !secondReverted &&
            ownerBefore == ownerAfterFirst &&
            ownerAfterFirst == ownerAfterSecond &&
            ownerAfterFirst == c.owner()
        );
    }

    receive() external payable {}
}
